const $=id=>document.getElementById(id),$$=s=>[...document.querySelectorAll(s)];
let level=0,mode='explore',tool='add',builds=Array.from({length:levels.length+1},()=>[]),history=Array.from({length:levels.length+1},()=>[]),completed=new Set(),checked=false,overlay=false,showTarget=true,finalExplore=false,predicted=false,solvedNow=false,predictView='front',choiceOptions=[];
const FREE=levels.length;
const isFree=()=>level===FREE;
const activity=()=>isFree()?{title:'Your Cube Workshop',tag:'FREE EXPLORE',prompt:'Create any model in the grid. Add or remove cubes, turn the view, and watch your drawings change.',cubes:builds[FREE]}:levels[level];
const titleCase=s=>s[0].toUpperCase()+s.slice(1);
const scene=new Scene($('scene'),{onEdit:edit,onViewChange:view=>$$('[data-view]').forEach(b=>{const active=b.dataset.view===view;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))})});
function instruction(element,text){element.replaceChildren();const pattern=/(\+ Add Cube|Rotate View|Show My Outline|Show My Target)/g;let end=0;for(const match of text.matchAll(pattern)){element.append(text.slice(end,match.index));const strong=document.createElement('strong');strong.className='action-name';strong.textContent=match[0];element.append(strong);end=match.index+match[0].length;}element.append(text.slice(end));}
function say(title,detail,success=false){$('feedback-title').textContent=title;instruction($('feedback'),detail);$('message-icon').textContent=success?'✓':'◇';document.querySelector('.action-bar').classList.toggle('success',success);decorateVocabulary($('feedback'));decorateVocabulary($('feedback-title'))}
function svgDrawing(p,{overlayDrawing=null,hidden=false,showDrawing=true}={}){const pad=18,cell=31,w=pad*2+cell*SIZE;let s=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${w}" aria-hidden="true">`;
for(let i=0;i<=SIZE;i++){const a=pad+i*cell;s+=`<path d="M${pad} ${a}H${w-pad}M${a} ${pad}V${w-pad}" stroke="#d4e0e3" stroke-width=".7"/>`}
if(hidden)return s+`<rect x="${pad}" y="${pad}" width="${cell*SIZE}" height="${cell*SIZE}" fill="#edf5f3" fill-opacity=".95"/><text x="${w/2}" y="${w/2+12}" text-anchor="middle" font-family="Comic Sans MS, Comic Sans, Comic Neue, cursive" font-size="40" fill="#4c7c74">?</text></svg>`;
if(showDrawing)for(const k of p.filled){const [x,y]=k.split(',').map(Number);s+=`<rect x="${pad+x*cell}" y="${pad+y*cell}" width="${cell+.05}" height="${cell+.05}" fill="#bbdfd5"/>`}
if(showDrawing)for(const [x1,y1,x2,y2] of p.edges)s+=`<path d="M${pad+x1*cell} ${pad+y1*cell}L${pad+x2*cell} ${pad+y2*cell}" fill="none" stroke="#225f58" stroke-width="2.1" stroke-linecap="square"/>`;
if(overlayDrawing)for(const [x1,y1,x2,y2] of overlayDrawing.edges)s+=`<path d="M${pad+x1*cell} ${pad+y1*cell}L${pad+x2*cell} ${pad+y2*cell}" fill="none" stroke="#bc6710" stroke-width="3" stroke-dasharray="4 3"/>`;
return s+'</svg>'}
function renderViews(){const result=checked&&!isFree()?check(builds[level],activity().cubes):null;for(const view of ['top','front','right']){const target=projection(activity().cubes,view),hidden=mode==='predict'&&view===predictView;const svg=$(`view-${view}`);const markup=svgDrawing(target,{hidden,showDrawing:isFree()||mode!=='build'||showTarget,overlayDrawing:!isFree()&&mode==='build'&&overlay?projection(builds[level],view):null});const parsed=new DOMParser().parseFromString(markup,'image/svg+xml').documentElement;svg.setAttribute('viewBox',parsed.getAttribute('viewBox'));svg.innerHTML=parsed.innerHTML;svg.setAttribute('aria-label',isFree()?`${titleCase(view)} live drawing of your construction`:hidden?`${titleCase(view)} view hidden for prediction`:`${titleCase(view)} drawing: ${mode==='build'&&!showTarget?'target hidden':'target shown'}${mode==='build'&&overlay?', your outline shown':''}, on a ${SIZE} by ${SIZE} grid`);const status=$(`status-${view}`);status.textContent=hidden?'Predict this':result?(result.views[view]?'✓ Matches':'Check this'):'';status.className='view-status'+(result?(result.views[view]?' match':' miss'):'')}
$('target-legend').hidden=isFree()||mode==='build'&&!showTarget;$('target-toggle').setAttribute('aria-pressed',String(showTarget));$('your-legend').hidden=isFree()||!(overlay&&mode==='build');$('overlay').setAttribute('aria-pressed',String(overlay))}
function renderNav(){
 const workshop=isFree()?'free':level===0?'learn':'challenge';
 $$('[data-workshop]').forEach(b=>{const active=b.dataset.workshop===workshop;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});
 $('levels').hidden=workshop!=='challenge';$('levels').replaceChildren();
 levels.slice(1).forEach((l,index)=>{const i=index+1,b=document.createElement('button');b.textContent=String(i);b.title=l.title;b.setAttribute('aria-label',`Puzzle ${i}: ${l.title}${completed.has(i)?', completed':''}`);b.setAttribute('aria-current',i===level?'step':'false');b.className=(i===level?'active ':'')+(completed.has(i)?'solved':'');b.onclick=()=>startLevel(i);$('levels').append(b);});
 document.querySelector('.mode-tabs').hidden=workshop!=='learn';
 document.querySelector('.comparison-toggles').hidden=isFree();
}
function setPrimary(text){$('primary-action').textContent=text+' →'}
function render(){document.body.className=`mode-${mode}`;renderNav();$('chapter').textContent=activity().tag;$('challenge-title').textContent=activity().title;instruction($('mission'),missionText());decorateVocabulary($('mission'));$('completion').hidden=isFree()||!(solvedNow||finalExplore);$('completion-title').textContent=completed.size===levels.length?'Every Mystery Solved!':level===levels.length-1?'Final Puzzle Solved!':'Mystery Solved!';$('completion-detail').textContent=finalExplore?`Explore your finished work. You have solved ${completed.size} of ${levels.length} activities. Choose Learn or a numbered puzzle to revisit it.`:'All three drawings match your construction. Take a moment to turn it around and enjoy what you built.';$$('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-pressed',String(b.dataset.mode===mode))});$$('[data-tool]').forEach(b=>{b.classList.toggle('active',b.dataset.tool===tool);b.setAttribute('aria-pressed',String(b.dataset.tool===tool))});const cubes=mode==='build'?builds[level]:activity().cubes;scene.set(cubes,mode==='build'?tool:'rotate');$('cube-count').textContent=`${cubes.length} ${cubes.length===1?'cube':'cubes'}`;$('model-heading').textContent=mode==='build'?'Your Model':'The Model';$('scene-tag').textContent=mode==='build'?(tool==='rotate'?'DRAG TO ROTATE':tool==='add'?'CLICK A FACE TO ADD':'CLICK A CUBE TO REMOVE'):'DRAG TO ROTATE';$('interaction-note').textContent=mode==='build'?(tool==='rotate'?'Rotate View: drag to turn · Clicking does not edit cubes':'Click to edit · Drag to turn · Arrow keys to turn'):'Drag to turn · Scroll to zoom · Arrow keys to turn';$('undo').disabled=history[level].length===0;$('reset').disabled=builds[level].length===0;$('prediction-panel').hidden=mode!=='predict';$('board-key').innerHTML=isFree()?'These are live drawings<br>of your own construction.':mode==='build'?'Match the outside outline<br>and the visible inside edges.':'The drawings stay fixed<br>as you rotate the model.';renderViews();if(isFree())setPrimary('Check Construction');else if(finalExplore)setPrimary('Return To Learn');else if(mode==='explore')setPrimary('Try A Prediction');else if(mode==='predict')setPrimary(predicted?'Build This Model':'Choose A Drawing');else setPrimary(solvedNow?(level===levels.length-1?'Explore The Final Model':'Next Puzzle'):'Check My Model');$('primary-action').disabled=mode==='predict'&&!predicted;decorateVocabulary(document.querySelector('.brief'));decorateVocabulary($('board-key'));decorateVocabulary($('completion'));decorateVocabulary(document.querySelector('main'));}
function missionText(){
 if(isFree())return activity().prompt;
 if(finalExplore)return 'You solved the final puzzle! Rotate the model, revisit another puzzle, or explain how the three views fit together.';
 if(level===0&&mode==='build')return 'Your turn! Build a 3D model that matches the Top, Front, and Right drawings. Choose the green + Add Cube button below, then click the base to place your first cube. Click a cube face to add the next cube.';
 if(level===0&&mode==='predict')return 'Look at the 3D model. Predict the missing view, then choose its matching drawing below the model.';
 if(mode==='explore')return 'You can rotate the 3d model on the left!\nThe same model is depicted on the right- but from three different perspectives: Top, Front, and Right.';
 return activity().prompt;
}
function setMode(next){if(isFree()&&next!=='build')throw Error('Free Explore uses the building tools.');if(level>0&&level<FREE&&next!=='build'&&!completed.has(level))throw Error('Solve this challenge before revealing its model.');if(!['explore','predict','build'].includes(next))throw Error('Choose Explore, Predict, or Build.');mode=next;finalExplore=false;checked=false;solvedNow=false;predicted=false;if(mode==='explore')say('Start With A Different Viewpoint','Choose Front, Top, and Right. Which view hides the most cubes?');if(mode==='predict'){predictView=['front','right','top'][level%3];makePrediction();say('Look Before You Choose',`Which drawing matches the ${predictView} view? You can rotate the model to help.`)}if(isFree()){tool='add';say('Your Ideas, Your Workshop','Use all the cube tools freely. The three drawings update as you build.');}else if(mode==='build'){tool='add';say('Build The Object Shown In The Drawings.','Choose + Add Cube, then click the base to place your first cube. Click cube faces to add more.');}render()}
function startLevel(i){if(!Number.isInteger(i)||i<0||i>FREE)throw Error('Choose Learn, a puzzle, or Free Explore.');level=i;overlay=false;showTarget=true;scene.setView('iso');setMode(i===0?'explore':'build')}
function snapshot(){history[level].push(structuredClone(builds[level]));if(history[level].length>100)history[level].shift()}
function edit(cell,action){if(mode!=='build')return{ok:false,message:'Switch to Build to edit cubes.'};if(!inside(cell)){say('Stay Inside The Building Space','Use columns, heights, and depths from 1 to 4.');return{ok:false,message:'Out of bounds'}}const s=new Set(builds[level].map(key)),k=key(cell);if(action==='add'&&s.has(k)){say('There Is Already A Cube Here','Choose an empty space or click another face.');return{ok:false,message:'Occupied'}}if(action==='remove'&&!s.has(k)){say('This Space Is Already Empty','Choose a cube to remove.');return{ok:false,message:'Empty'}}snapshot();if(action==='add')s.add(k);else if(action==='remove')s.delete(k);else throw Error('Unknown edit action');builds[level]=[...s].map(unkey);checked=false;solvedNow=false;render();if(isFree())say('Your Drawings Updated','Try a different height or depth. What changed in each view?');else say('Keep Checking All Three Views','Use “Show My Outline” to compare your model with the target.');return{ok:true,cubes:builds[level].length}}
function verify(){if(isFree()){const result=rules(builds[FREE]);say(result.ok?'Connected And Supported!':'Check Your Construction',result.ok?'Your construction follows the building rules. Keep experimenting; there is no target to match.':result.reason,result.ok);return {rules:result,solved:false};}checked=true;const result=check(builds[level],activity().cubes);solvedNow=result.solved;if(result.solved){completed.add(level);$('completion').classList.remove('celebrate');void $('completion').offsetWidth;$('completion').classList.add('celebrate');say('All Three Views Match. You Solved It!',level===5?'Build this one with snap cubes, then sketch and explain the three views.':'Before moving on: which view helped you most, and why?',true)}else if(!result.rules.ok)say('Check Your Construction',result.rules.reason);else{const yes=Object.keys(result.views).filter(v=>result.views[v]),no=Object.keys(result.views).filter(v=>!result.views[v]);say(yes.length?`${yes.map(titleCase).join(' and ')} ${yes.length===1?'view matches':'views match'}.`:'Let’s Compare The Drawings',`Check ${no.map(titleCase).join(' and ')}. ${levels[level].hint}`)}render();return result}
function makePrediction(){choiceOptions=predictionOptions(activity().cubes,predictView,level);$('predict-view-name').textContent=titleCase(predictView);$('prediction-choices').innerHTML='';choiceOptions.forEach((option,i)=>{const b=document.createElement('button');b.setAttribute('aria-label',`Choose drawing ${String.fromCharCode(65+i)}`);b.innerHTML=svgDrawing(option.drawing)+`<span>${String.fromCharCode(65+i)}</span>`;b.onclick=()=>{if(option.correct){predicted=true;b.classList.add('correct');say('Yes—That Is The View!',`Now use all three drawings to build the object yourself.`,true);setPrimary('Build This Model');$('primary-action').disabled=false}else{b.classList.add('incorrect');say('Take Another Look',`Choose the ${titleCase(predictView)} camera button, then compare the outline and visible inside edges.`)}};$('prediction-choices').append(b)})}
$$('[data-workshop]').forEach(b=>b.onclick=()=>startLevel(b.dataset.workshop==='free'?FREE:b.dataset.workshop==='learn'?0:1));
$$('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));$$('[data-tool]').forEach(b=>b.onclick=()=>{tool=b.dataset.tool;render();if(tool==='rotate')say('Rotate View','Drag to inspect your model. Clicking will not add or remove cubes. Choose + Add Cube or − Remove to edit again.');});$$('[data-view]').forEach(b=>b.onclick=()=>scene.setView(b.dataset.view));$('zoom-in').onclick=()=>scene.zoomBy(1.1);$('zoom-out').onclick=()=>scene.zoomBy(1/1.1);$('overlay').onclick=()=>{overlay=!overlay;renderViews()};$('target-toggle').onclick=()=>{showTarget=!showTarget;renderViews()};$('undo').onclick=()=>{if(!history[level].length)return;builds[level]=history[level].pop();checked=false;solvedNow=false;render();say('Last Edit Undone','Keep building, or check the three views again.')};$('reset').onclick=()=>{if(!builds[level].length)return;snapshot();builds[level]=[];checked=false;solvedNow=false;render();say('A Fresh Start','Your previous model is still one Undo away.')};for(const axis of ['x','y','z'])for(let i=1;i<=SIZE;i++){const o=document.createElement('option');o.value=i-1;o.textContent=i;$(`coord-${axis}`).append(o)}const chosenCell=()=>['x','y','z'].map(a=>Number($(`coord-${a}`).value));$('place-cube').onclick=()=>edit(chosenCell(),'add');$('remove-cube').onclick=()=>edit(chosenCell(),'remove');$('primary-action').onclick=()=>{if(isFree())return verify();if(finalExplore)return startLevel(0);if(mode==='explore')setMode('predict');else if(mode==='predict'&&predicted)setMode('build');else if(mode==='build'){if(solvedNow){if(level===levels.length-1){setMode('explore');finalExplore=true;render();say('Final Puzzle Solved!',`You have solved ${completed.size} of ${levels.length} activities. Explore this model or choose an earlier puzzle.`,true);}else startLevel(level+1)}else verify()}};$('help-open').onclick=()=>$('help').showModal();$('help-close').onclick=()=>$('help').close();$('help').addEventListener('click',e=>{if(e.target===$('help')){const r=$('help').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('help').close()}});
