const state=()=>({challenge:isFree()?null:level,workshop:isFree()?'free':level===0?'learn':'challenge',title:activity().title,mode,cubes:structuredClone(mode==='build'?builds[level]:activity().cubes),completed:[...completed],checked,solved:solvedNow});
const context=document.modelContext;if(context?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}};register({name:'read_multiview_workshop',description:'Read the current puzzle, mode, and displayed cubes.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>state()});register({name:'start_multiview_challenge',description:'Select a challenge (0 is the guided example; 1–5 are puzzles) and workshop mode.',inputSchema:{type:'object',properties:{challenge:{type:'integer',minimum:0,maximum:5},mode:{type:'string',enum:['explore','predict','build']}},required:['challenge','mode'],additionalProperties:false},execute:input=>{if(!input||!Number.isInteger(input.challenge)||input.challenge<0||input.challenge>5||!['explore','predict','build'].includes(input.mode))throw Error('Invalid challenge or mode');startLevel(input.challenge);setMode(input.mode);return state()}});register({name:'start_free_explore',description:'Open the unrestricted cube workshop with live drawings.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:()=>{startLevel(FREE);return state();}});register({name:'edit_multiview_cubes',description:'Add or remove cube cells in Build mode. Coordinates are zero-based, 0–3. Applies edits to the visible model.',inputSchema:{type:'object',properties:{action:{type:'string',enum:['add','remove']},cells:{type:'array',minItems:1,maxItems:64,items:{type:'array',minItems:3,maxItems:3,items:{type:'integer',minimum:0,maximum:3}}}},required:['action','cells'],additionalProperties:false},execute:input=>{if(!input||!['add','remove'].includes(input.action)||!Array.isArray(input.cells)||!input.cells.length||input.cells.length>64||input.cells.some(c=>!inside(c)))throw Error('Invalid cube edit');if(mode!=='build')throw Error('Switch to Build first');const results=input.cells.map(c=>edit(c,input.action));return{results,state:state()}}});register({name:'check_multiview_model',description:'Check the current construction against all three target drawings and the build rules.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:()=>{if(mode!=='build')throw Error('Switch to Build first');return verify()}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
